{
  "findings": [
    {
      "check_id": "CKV_GCP_83",
      "title": "Pub/Sub topic is not encrypted with a customer-managed key",
      "resource": "google_pubsub_topic.notification_queue",
      "severity": "MEDIUM",
      "explanation": "The production Pub/Sub topic does not specify kms_key_name, so it relies on Google-managed encryption keys rather than a customer-managed key with independently controlled rotation and access."
    }
  ],
  "patched_code": "variable "pubsub_kms_key_name" {
  description = "Fully qualified resource name of the customer-managed Cloud KMS key used to encrypt the Pub/Sub topic."
  type        = string
  nullable    = false
}

resource "google_pubsub_topic" "notification_queue" {
  name         = "insurance-claims-processing-platform-pubsub-notifications"
  kms_key_name = var.pubsub_kms_key_name

  labels = {
    environment = "production"
    component   = "notifications"
  }
}
",
  "fix_summary": "Added a required variable for an existing customer-managed Cloud KMS key and configured the Pub/Sub topic to use it for encryption."
}
